const canvas = document.getElementById('touch-canvas');
        const ctx = canvas.getContext('2d');
        const pointsDisplay = document.getElementById('active-points');
        const coordsDisplay = document.getElementById('coordinate-readout');
        const rateDisplay = document.getElementById('rate-display');
        const typeDisplay = document.getElementById('pointer-type-display');
        let activePointers = new Map();
        let lastEventTime = 0;
        let eventCount = 0;
        let lastRateCheck = 0;
        // Resize canvas to fit container
        function resizeCanvas() {
            const rect = canvas.getBoundingClientRect();
            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            ctx.scale(dpr, dpr);
            // Reset composite op after resize just in case
            ctx.globalCompositeOperation = 'source-over';
        }
        window.addEventListener('load', () => {
            resizeCanvas();
            // Initial black background
            clearCanvas();
        });
        window.addEventListener('resize', resizeCanvas);
        function clearCanvas() {
            const rect = canvas.getBoundingClientRect();
            ctx.fillStyle = '#1e293b'; // Matches BG color
            ctx.fillRect(0, 0, rect.width, rect.height);
            activePointers.clear();
            updateDisplay();
        }
        function toggleFullscreen() {
            if (!document.fullscreenElement) {
                canvas.requestFullscreen().catch(err => {
                    alert(`Error attempting to enable full-screen mode: ${err.message} (${err.name})`);
                });
            } else {
                document.exitFullscreen();
            }
        }
        // Pointer Event Handlers
        canvas.addEventListener('pointerdown', handlePointerDown);
        canvas.addEventListener('pointermove', handlePointerMove);
        canvas.addEventListener('pointerup', handlePointerUp);
        canvas.addEventListener('pointercancel', handlePointerUp);
        canvas.addEventListener('pointerout', handlePointerUp);
        canvas.addEventListener('pointerleave', handlePointerUp);
        function handlePointerDown(e) {
            e.preventDefault();
            activePointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY, color: getRandomColor() });
            canvas.setPointerCapture(e.pointerId);
            updateDisplay();
            typeDisplay.innerText = e.pointerType.toUpperCase();
            // Draw initial dot
            drawPoint(e.offsetX, e.offsetY, e.pressure, activePointers.get(e.pointerId).color);
        }
        function handlePointerMove(e) {
            e.preventDefault();
            // Calculate polling rate
            const now = performance.now();
            eventCount++;
            if (now - lastRateCheck > 1000) {
                rateDisplay.innerText = `${eventCount} Hz`;
                eventCount = 0;
                lastRateCheck = now;
            }
            if (activePointers.has(e.pointerId)) {
                const point = activePointers.get(e.pointerId);
                // Draw line from last pos to current
                ctx.beginPath();
                ctx.moveTo(point.x, point.y);
                ctx.lineTo(e.offsetX, e.offsetY);
                ctx.strokeStyle = point.color; // Unique color per finger
                ctx.lineWidth = Math.max(2, e.pressure * 20); // Pressure sensitivity
                ctx.lineCap = 'round';
                ctx.stroke();
                // Update stored position
                point.x = e.offsetX;
                point.y = e.offsetY;
                coordsDisplay.innerText = `X: ${Math.round(e.offsetX)} | Y: ${Math.round(e.offsetY)}`;
            } else {
                // Hover state
                coordsDisplay.innerText = `X: ${Math.round(e.offsetX)} | Y: ${Math.round(e.offsetY)}`;
            }
        }
        function handlePointerUp(e) {
            e.preventDefault();
            activePointers.delete(e.pointerId);
            updateDisplay();
            if (activePointers.size === 0) {
                // rateDisplay.innerText = "-- Hz";
            }
        }
        function updateDisplay() {
            pointsDisplay.innerText = activePointers.size;
        }
        function drawPoint(x, y, pressure, color) {
            ctx.beginPath();
            ctx.arc(x, y, Math.max(5, pressure * 10), 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
        }
        function getRandomColor() {
            // Return bright cyan/teal variants for visibility on dark BG
            const hue = 170 + Math.random() * 40; // Cyan to Blue range
            return `hsl(${hue}, 100%, 60%)`;
        }
        // --- SCROLL LOGIC ---
